async function getCausalStrengthEdges(req, res) {
    let _fn = `getCausalStrengthEdges`
    let opts = req.body
    // retrieve model name
    let edge_strength = {}
    let intrinsic_effects = {}
    let causal_mechanisms = {}
    let local_markov_test = {}
    let edge_dependence_test = {}
    let flow_info = runtime._.flows.getFlow(opts.activeWorkspace)
    let tx = ""
    try {
        let query_opts = {
            "db": "causeway-repo",
            // "query": match,
            "query_type": "match",
            "session_type": "DATA",
            "transaction_type": "READ",
            "caller": "get-causal-edgestrengths"
        }
        // await typedb.prepareExecuteQuery(query_opts)
        // match the nrid of the causal path : Typ
        if (flow_info !== null && opts.parent_child !== null) {
            for await (let node of flow_info.nodes) {
                if (node.type === "causeeffect" || node.type === "moderator") {
                    // console.log(`\n ${node.name}`)
                    if (node.hasOwnProperty("wires")) {
                        for await (let effect of node.wires[0]) {
                            // match the the causal path of parent to child using parent.id and child.id
                            let unique_path_id = node.id + "_" + effect
                            let match = "match $cp isa causal_path, has nrid \"" + unique_path_id + "\";\n"
                            query_opts["query"] = match
                            // let typedb api handle executing query
                            let query_result = await typedb.executeQuery(query_opts)
                            // console.log(`${_module} ${_fn} query results `, query_result.length)
                            // get transaction type instance for access to remote concepts functionality
                            tx = await typedb.get_transaction(query_opts)
                            // console.log(`${_module} ~${_fn}~ typeof tx`, typeof tx)

                            // iterate through results; should be of length 1 
                            if (typeof tx !== 'string') {
                                // console.log("type of tx ", tx, typeof tx)

                                if (tx.isOpen()) {
                                    if (query_result.length > 0) {
                                        for await (let result of query_result) {
                                            // console.log(`${_module} ${_fn} result `, result)
                                            let causal_path = await result.get("cp").asRemote(tx)
                                            let attributes = await causal_path.getHas().collect()
                                            // console.log("length of attributes: ", attributes.length)
                                            for await (let attribute of attributes) {
                                                // console.log(attribute.type.label.name)
                                                if (attribute.type.label.name === "edge_strength") {
                                                    // attribute_value = attribute.value.split(":")
                                                    if (edge_strength[effect]) {
                                                        edge_strength[effect] = { ...edge_strength[effect], [node.id]: attribute.value }
                                                    } else {
                                                        edge_strength[effect] = { [node.id]: attribute.value }
                                                    }
                                                }
                                                if (attribute.type.label.name === "intrinsic_effects") {
                                                    if (intrinsic_effects[effect]) {
                                                        intrinsic_effects[effect] = { ...intrinsic_effects[effect], [node.id]: attribute.value }
                                                    } else {
                                                        intrinsic_effects[effect] = { [node.id]: attribute.value }
                                                    }
                                                }
                                                if (attribute.type.label.name === "causal_mechanisms") {
                                                    if (causal_mechanisms[effect]) {
                                                        causal_mechanisms[effect] = { ...causal_mechanisms[effect], [node.id]: attribute.value }
                                                    } else {
                                                        causal_mechanisms[effect] = { [node.id]: attribute.value }
                                                    }
                                                }
                                                if (attribute.type.label.name === "local_markov_test") {
                                                    if (local_markov_test[effect]) {
                                                        local_markov_test[effect] = { ...local_markov_test[effect], [node.id]: attribute.value }
                                                    } else {
                                                        local_markov_test[effect] = { [node.id]: attribute.value }
                                                    }
                                                }
                                                if (attribute.type.label.name === "edge_dependence_test") {
                                                    if (edge_dependence_test[effect]) {
                                                        edge_dependence_test[effect] = { ...edge_dependence_test[effect], [node.id]: attribute.value }
                                                    } else {
                                                        edge_dependence_test[effect] = { [node.id]: attribute.value }
                                                    }
                                                }
                                            }
                                        }
                                    }
                                }
                            } else {
                                throw "No models deployed yet"
                            }
                            await typedb.close_transaction(query_opts.transaction_type, tx)
                            if (tx.isOpen()) {
                                await typedb.close_session()
                            }
                        }
                    }


                    //  HANDLE RETRIEVING CM COEFFICIENT + OTHER VALUES THAT THE NODE ITSELF STORES SUCH AS INTRINSIC EFFECT NOISE, ETC.
                    let match = "match $cp isa causeeffect, has nrid \"" + node.id + "\";\n"
                    query_opts["query"] = match
                    // let typedb api handle executing query
                    let query_result = await typedb.executeQuery(query_opts)
                    tx = await typedb.get_transaction(query_opts)
                    // iterate through results; should be of length 1 
                    if (typeof tx !== 'string') {
                        if (tx.isOpen()) {
                            if (query_result.length > 0) {
                                for await (let result of query_result) {
                                    let causal_path = await result.get("cp").asRemote(tx)
                                    let attributes = await causal_path.getHas().collect()
                                    // console.log("length of attributes: ", attributes.length)
                                    for await (let attribute of attributes) {
                                        // console.log("Attribute label type: ", attribute.type.label.name)
                                        // FIND ALL ANALYSIS TYPES FOR AN EFFECT NODE
                                        // included intrinsic_effects, causal_mechanisms as coefficients, local markov test
                                        // excluded: edge_strength for variance 
                                        if (attribute.type.label.name === "intrinsic_effects") {
                                            if (intrinsic_effects[node.id]) {
                                                intrinsic_effects[node.id] = { ...intrinsic_effects[node.id], [node.id]: attribute.value }
                                            } else {
                                                intrinsic_effects[node.id] = { [node.id]: attribute.value }
                                            }
                                        }
                                        if (attribute.type.label.name === "causal_mechanisms") {
                                            // console.log(`causal mechanisms attribute value ` ,attribute.value, typeof attribute.value)
                                            if (causal_mechanisms[node.id]) {
                                                causal_mechanisms[node.id] = { ...causal_mechanisms[node.id], [node.id]: attribute.value }
                                            } else {
                                                causal_mechanisms[node.id] = { [node.id]: attribute.value }
                                            }
                                        }
                                        if (attribute.type.label.name === "local_markov_test") {
                                            if (local_markov_test[node.id]) {
                                                local_markov_test[node.id] = { ...local_markov_test[node.id], [node.id]: attribute.value }
                                            } else {
                                                local_markov_test[node.id] = { [node.id]: attribute.value }
                                            }
                                        }
                                        if (attribute.type.label.name === "edge_dependence_test") {
                                            if (edge_dependence_test[node.id]) {
                                                edge_dependence_test[node.id] = { ...edge_dependence_test[node.id], [node.id]: attribute.value }
                                            } else {
                                                edge_dependence_test[node.id] = { [node.id]: attribute.value }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    } else {
                        throw "No models deployed yet"
                    }

                    if (tx.isOpen()) {
                        await typedb.close_transaction(query_opts.transaction_type, tx)
                    }

                }
            }
        }
        return [edge_strength, intrinsic_effects, causal_mechanisms, local_markov_test, edge_dependence_test]
    } catch (exception) {
        console.log(`${_module} [getCausalStrengthEdges] throw exception`, exception)
        throw exception
    }
}

