async function getLicense(req, res) {
    let prefix = "getLicense"
    console.log(`${prefix} getLicense Getting license`)

    try {
        // check if license exists inside of TypeDB
        let match = "match $license isa license, has id \"geminos-license\";\n"
        let query_opts = {
            "db": "causeway-repo",
            "query": match,
            "query_type": "match",
            "session_type": "DATA",
            "transaction_type": "READ",
            "caller": "get-license"

        }
        // let typedb api handle executing query
        let query_result = await typedb.executeQuery(query_opts)

        // need to open a session 

        // set database
        await typedb.set_database(query_opts["db"])
        // create session to database
        await typedb.create_session(query_opts)
        let tx = await typedb.get_transaction(query_opts)
        // iterate through results; should be of length 1 
        if (typeof tx !== 'string') {
            if (tx.isOpen()) {
                // console.log(`${prefix} getLicense query result`, query_result)
                if (query_result.length > 0) {

                    let license = {
                        message: "ok",
                    }
                    let _license = await query_result[0].get("license").asRemote(tx)
                    let attributes = await _license.getHas().collect()
                    // console.log("length of attributes: ", attributes.length)
                    for await (let attribute of attributes) {
                        // console.log("Attribute label type: ", attribute.type.label.name)
                        license[attribute.type.label.name] = attribute.value
                    }
                    // console.log(`${prefix} getLicense license `, license)
                    // license exists
                    res.status(200).send(license)
                } else {
                    res.status(500).send({ error: "No validated license found" })
                }
            }
        }
        await typedb.close_transaction(query_opts.transaction_type, tx)

    } catch (exception) {
        console.log(exception)
        res.status(500).send({ error: exception })
    }

}

async function validateLicense(req, res) {
    let prefix = "validateLicense"
    try {
        // console.log(`${prefix} request object `, req.query)

        const licenseKey = req.query.licenseKey
        // console.log(`${prefix} licenseKey`, licenseKey)

        const userInfo = {
            name: 'Geminos.ai',
            country: 'USA',
            town: 'Remote',
            zip: 'Remote',
            address: 'Remote',
            // "name": req.query.name,
            // "email": req.query.email,
            // "phone": req.query.phone,
        }

        // create license with config data providied and iterate through the version to make sure the keys are valid
        let versionTypes = ["1.3.1.0", ""]
        let validated_license = {}
        let licenseTypes = ["DSC", "DSCPRO"]
        for await (let licenseType of licenseTypes) {
            // console.log(`\n ======\n${prefix} license type `, licenseType)
            for await (let vtype of versionTypes) {
                try {
                    // console.log(`\n ======\n${prefix} vtype ${vtype} `)
                    let configData = {
                        info: userInfo,
                        validity: req.query.validity,
                        prodCode: "CAUSEWAY",
                        appVersion: vtype + licenseType,
                    }
                    const valid_license = LicenseGen.validateLicense(configData, licenseKey)
                    if (valid_license.message === "ok") {
                        validated_license = valid_license
                    }
                } catch (exception) {
                    // console.log(`${prefix} validating license exception `, exception)
                }
            }
        }
        if (validated_license.message === "ok") {
            causeway_config.type = validated_license._appVersion
            causeway_config.productCode = validated_license._prodCode
            console.log(`\n ${prefix} valid license key ✅ `)

            await storeLicense(validated_license).then((response) => {
                if (response) {
                    res.status(200).send(validated_license)
                }
            }).catch(() => {
                throw "Unable to validate key correctly"
            })

        } else {
            throw "Unable to validate key correctly"
        }
    } catch (exception) {
        console.log("exception for validating license: ", exception)
        res.status(500).send({ error: exception })
    }
}

async function storeLicense(license) {
    let prefix = "[storeLicense]"
    try {
        // check if database exists
        let query_opts = {
            "db": "causeway-repo",
            "query": "",
            "query_type": "match",
            "session_type": "DATA",
            "transaction_type": "READ",
            "caller": "store-license"
        }
        let query_result = {}
        let msg = ""
        // check if license exists inside of TypeDB
        query_opts["query"] = "match $license isa license , has id \"geminos-license\"; get $license;"
        query_opts["transaction_type"] = "READ"
        // console.log(`${prefix}  query opts `, query_opts)
        query_result = await typedb.executeQuery(query_opts)
        if (query_result.length > 0) {
            //  UPDATE validated license
            let updatedDate = new Date()
            query_opts["query_type"] = "update"
            query_opts["query"] =
                `match $license isa license, has id \"geminos-license\", has validated_on $date, has product_code $product, has license_key $licensekey, has validity $validity; delete $license has $date, has $validity, has $product, has $licensekey; insert $license has validated_on \"${updatedDate.toString()}\", has license_key \"${license.serial}\", has validity \"${license.validity}\", has product_code \"${license._prodCode}\";\n`
            query_opts["transaction_type"] = "WRITE"
            msg = `${prefix} UPDATED Validated license `
        } else {
            //  INSERT validated license 
            let date = new Date()
            query_opts["query_type"] = "insert"
            query_opts["query"] =
                `insert $license isa license, has id \"geminos-license\", has license_key \"${license.serial}\", has validated_on \"${date.toString()}\", has validity \"${license.validity}\", has product_code \"${license._prodCode}\";\n`
            query_opts["transaction_type"] = "WRITE"
            msg = `${prefix} INSERTED Validated license `
        }
        query_result = await typedb.executeQuery(query_opts)
        console.log(`${prefix} finished storing license ✅`)
        return true

    } catch (exception) {
        console.log(`${prefix} exception `, exception)
        throw exception
    }
}

