async function clearICC(req, res) {
    try {
        console.log("REQUEST AT CLEAR ICC ", req.body)
        if (req.body.hasOwnProperty("nn")) {
            // get total absolute value + clear previous ancestor values
            for await (let tempNodeID of Object.values(req.body["nn"])) {
                let ancestorNode = runtime._.nodes.getNode(tempNodeID)
                ancestorNode.status({});
                ancestorNode.highlightintrinsiceffects = false
            }
        }
        res.status(200).send("Successfully cleared all ICC values")
    } catch (exception) {
        console.log("Excpetion ", exception)
        res.status(500).send({ error: exception })
    }
}

async function updateICC(req, res) {
    try {
        let _fn = "@ updateICC"
        // get parents of the current node
        if (req.body.hasOwnProperty("parents")) {
            let icc_values = {}
            let ancestors = []
            try {
                let url = uri + ":" + port + "/digraph/ancestors/" + req.body["activeWorkspace"]
                // console.log("URL ", url)
                // console.log(req.body["nodeName"])
                ancestors = await axios.get(url, {
                    params: {
                        "nodeID": req.body["nodeName"],
                    },
                }).then(async (api_res) => {
                    if (api_res.status == 200) {
                        return api_res.data
                    }
                }).catch((err) => {
                    throw err
                })
            } catch (exception) {
                console.error("exception occurred : ", exception)
                throw exception
            }

            // // clear
            for await (let tempNodeID of Object.values(req.body.nn)) {
                let ancestorNode = runtime._.nodes.getNode(tempNodeID)
                ancestorNode.highlightintrinsiceffects = false
                ancestorNode.status({});
            }

            let query_opts = {
                "db": "causeway-repo",
                // "query": match,
                "query_type": "match",
                "session_type": "DATA",
                "transaction_type": "READ",
                "caller": "updateICC"
            }

            await typedb.prepareExecuteQuery(query_opts)
            for await (let parent of ancestors) {
                let parent_id = req.body.nn[parent]
                // query for each parent the current ICC value
                let unique_path_id = parent_id + "_" + req.body.nodeID
                let match = "match $cp isa causal_path, has nrid \"" + unique_path_id + "\", has intrinsic_effects $icc; get $icc;\n"
                query_opts["query"] = match
                // set database
                // let typedb api handle executing query
                let query_result = await typedb.executeQuery(query_opts)

                let tx = await typedb.get_transaction(query_opts)
                // iterate through results; should be of length 1 
                if (typeof tx !== 'string') {
                    if (tx.isOpen()) {
                        if (query_result.length > 0) {
                            for await (let result of query_result) {
                                let value = await result.get("icc").asRemote(tx)
                                value = value._value
                                value = (typeof value === "string") ? Number.parseFloat(value) : value
                                icc_values = { ...icc_values, [parent_id]: value }
                            }
                        }
                        await typedb.close_transaction(query_opts.transaction_type, tx)
                    }
                }

            }


            // get icc value for current node 
            let match = "match $cp isa causeeffect, has nrid \"" + req.body.nodeID + "\", has intrinsic_effects $icc; get $icc;\n"
            query_opts = {
                "db": "causeway-repo",
                "query": match,
                "query_type": "match",
                "session_type": "DATA",
                "transaction_type": "READ",
                "caller": "updateICC"
            }
            // let typedb api handle executing query
            await typedb.prepareExecuteQuery(query_opts)
            let query_result = await typedb.executeQuery(query_opts)
            let tx = await typedb.get_transaction(query_opts)
            // iterate through results; should be of length 1 
            if (typeof tx !== 'string') {
                // console.log("type of tx ", tx, typeof tx)
                // console.log("transaction is open: ", tx.isOpen())
                if (tx.isOpen()) {
                    if (query_result.length > 0) {
                        for await (let result of query_result) {
                            let value = await result.get("icc").asRemote(tx)
                            value = value._value
                            value = (typeof value === "string") ? Number.parseFloat(value) : value
                            icc_values = { ...icc_values, [req.body.nodeID]: value }
                        }
                    }
                }
            }
            await typedb.close_transaction(query_opts.transaction_type, tx)
            console.log(`${_module} ${_fn} ICCVALUES `, icc_values)


            // iterate through all the ICC values to calcualte total abs
            let total_abs = 0
            for await (let icc_value of Object.values(icc_values)) {
                total_abs += icc_value
            }
            console.log(`${_module} ${_fn} total abs `, total_abs)

            //  calculate percentage per node and display icc value
            for await (let causeId of Object.keys(icc_values)) {
                let ancestorNode = runtime._.nodes.getNode(causeId)
                value = icc_values[causeId]
                value = (value / total_abs * 100)
                // calculate number of decimals needed 
                let decimalCount = Math.abs(value - Math.floor(value))
                if (decimalCount <= 0.9) {
                    decimalCount = 2
                } else {
                    decimalCount = 5
                }

                let fill = "green"
                value = value.toLocaleString(undefined, { maximumFractionDigits: 2, minimumFractionDigits: 0 })
                if (value < 0) {
                    fill = "red"
                }
                if (value === "-0" || value === "0") {
                    fill = "grey"
                    value = "0"
                }
                ancestorNode.status({ "fill": fill, "shape": "dot", "text": value + "%" });
            }
        }

        console.log(`${_module} ${_fn} update ICC finished ✅`)
        res.send(`${_module} ${_fn} update ICC finished ✅`)
    } catch (exception) {
        console.log("Excpetion ", exception)
        res.status(500).send({ error: exception })
    }
}

async function updateCausalMechanism(req, res) {
    try {
        let _fn = `@@updateCausalMechanism`
        console.log(_fn, " request :  ", req.body)
        // call api server to handle processing data info
        let causal_inf_uri = uri + ":" + port + "/update-causal-mechanism/" + req.body["model_id"]
        console.log(_fn, " causal inf uri:  ", causal_inf_uri)
        try {
            await axios({
                method: "post",
                url: causal_inf_uri,
                data: req.body
            }).then(async (api_res) => {
                if (api_res.status !== 200) {
                    throw api_res.statusText
                } else {
                    let node = runtime._.nodes.getNode(req.body.node_id)
                    if (api_res.data.hasOwnProperty("causalmechanism")) {
                        node.causalmechanism = api_res.data.causalmechanism
                    }
                    if (api_res.data.hasOwnProperty("edgestrength")) {
                        node.edgestrength = api_res.data.edgestrength
                    }
                    res.send(api_res.data)
                }
            }).catch((err) => {
                console.log(err.response)
                throw err.response.statusText
            })
        } catch (exception) {
            console.log(_fn, " exception ", exception.response)
            res.status(500).send({ error: exception })
        }
    } catch (exception) {
        console.log("ERROR while udpatingCausalMechanism", exception.toString())
    }
}

async function queryLinkColor(req, res) {
    let _fn = `@queryLinkColor`
    try {
        // let typedb api handle executing query for min and max
        if (req.query.hasOwnProperty("inputs")) {
            // console.log(`RED.query.inputs `, req.query.inputs)
            if (req.query.inputs.length > 0) {
                let input_minmax = {}
                // initialize dict for for inputs 
                for await (let input of req.query.inputs) {
                    if (input_minmax.hasOwnProperty(input.kgId)) {
                        input_minmax[input.kgId] = { [input.conceptName]: {} }
                    }
                    else {
                        input_minmax[input.kgId] = { ...input_minmax[input.kgId], [input.conceptName]: {} }
                    }
                }

                for await (let input of req.query.inputs) {
                    /**  MIN QUERY EXAMPLE
                         match $e isa Company, 
                        has Revenue $rev;
                        min $rev; 
                    */

                    // check the type of the attribute and write query accordingly
                    let minQuery = ""
                    let maxQuery = ""
                    if (input.attributeType === "long" || input.attributeType === "double") {
                        minQuery = `match $concept isa ${input.conceptName}, has ${input.attributeName} $attr; min $attr;`
                        maxQuery = `match $concept isa ${input.conceptName}, has ${input.attributeName} $attr; max $attr;`
                    }

                    input_minmax[input.kgId][input.conceptName] = {
                        ...input_minmax[input.kgId][input.conceptName],
                        [input.attributeName]: {
                            "nodeName": input.nodeName,
                            "effectName": input.effectName,
                            "db": input.kgId,
                            "query": {
                                "query_type": "aggregate",
                                "session_type": "DATA",
                                "transaction_type": "READ",
                                "min": minQuery,
                                "max": maxQuery
                            },
                            "caller": "queryLinkColor",
                            "attributeType": input.attributeType
                        }
                    }
                }

                // send to causeway api to
                try {
                    let url = uri + ":" + port + "/data/aggregate"
                    await axios.get(url, {
                        params: {
                            "input_minmax": input_minmax,
                        },
                    }).then(async (api_res) => {
                        if (api_res.status == 200) {
                            res.send(api_res.data)
                        }
                    }).catch((err) => {
                        throw err
                    })
                } catch (exception) {
                    console.error("exception occurred : ")
                    throw exception
                }
            }
        }
        return
    } catch (exception) {
        console.log(`${_fn} exception `, exception)
    }

}

